sys_script.script:
(function executeRule(current, previous) {
    // Material, supplier, workforce, quality and machine constraints for every new draft schedule
    // (on top of the scheduler's own priority / due date / capacity / efficiency / maintenance logic).
    if (current.production_order.nil() || current.getValue('status') != 'draft' || (current.getValue('notes') || '').indexOf('Constraint check') > -1) {
        return;
    }
    var po = current.production_order.getRefRecord();
    var res = current.production_resource.getRefRecord();
    if (!po.isValidRecord()) {
        return;
    }
    var start = new GlideDateTime(current.getValue('planned_start') || new GlideDateTime().getValue());
    var end = new GlideDateTime(current.getValue('planned_end') || start.getValue());
    var days = Math.max(1, Math.ceil((end.getNumericValue() - start.getNumericValue()) / 86400000));
    var c = new x_2056099_indust_0.PlanningConstraints().evaluate(po,
        { sys_id: res.isValidRecord() ? res.getUniqueValue() : '', resource_name: res.isValidRecord() ? res.getValue('resource_name') : '' },
        { planned_start: start.getValue(), planned_end: end.getValue(), days_needed: days });
    if (c.blocked) {
        gs.addErrorMessage(c.reason);
        current.setAbortAction(true);
        return;
    }
    current.setValue('planned_start', c.dates.planned_start);
    current.setValue('planned_end', c.dates.planned_end);
    if (c.machine && current.machine.nil()) {
        current.setValue('machine', c.machine);
    }
    current.setValue('notes', (c.summary + (current.getValue('notes') ? ' | ' + current.getValue('notes') : '')).substring(0, 4000));
})(current, previous);
